import sys
import math
MAXNUM = math.inf
MINNUM = -1 * math.inf
ASCIILOWER = 97
ASCIIUPPER = 65

def getInt():
	return int(sys.stdin.readline().rstrip())

def getInts():
	return map(int, sys.stdin.readline().rstrip().split(' '))

def getString():
	return sys.stdin.readline().rstrip()

def printOutput(ans):
	sys.stdout.write(str(ans) + '\n')

def solve(h, n):
	heightNodes = [1 for _ in range(51)]
	for height in range(1, 51):
		heightNodes[height] = 2 ** height + heightNodes[height - 1]
	curPos = 2 ** (h - 1)
	depth = h
	add = 2 ** (h - 1)
	direction = -1
	total = 0
	while True:
		if depth == 0:
			break
		if curPos >= n and direction == -1 or (curPos < n and direction == 1):
			total += 1
			depth -= 1
			add //= 2
			curPos += direction * add
		else:
			total += heightNodes[depth - 1]
		direction *= -1
	return total

def readinput():
	(h, n) = getInts()
	printOutput(solve(h, n))
readinput()
